from pathlib import Path

p = Path('.github/workflows/starcore-tianshu-b06-runner.yml')
s = p.read_text(encoding='utf-8')
start_marker = "          python3 - <<'PY'\n"
end_marker = "          if grep -RIlF \"$KEY\" app/src reports tools .github/starcore-tianshu-b06 --exclude='B06_LIVE_API_TEST.json' 2>/dev/null | grep -q .; then\n"
if s.count(start_marker) != 1:
    raise SystemExit('API_START_MATCH_COUNT=' + str(s.count(start_marker)))
if s.count(end_marker) != 1:
    raise SystemExit('API_END_MATCH_COUNT=' + str(s.count(end_marker)))
a = s.index(start_marker)
b = s.index(end_marker, a)
replacement = "          python3 - <<'PY' | tee reports/B06_LIVE_API_TEST.log\n          import datetime, hashlib, json, os, re, time, urllib.parse, urllib.request\n          key=os.environ['DUOQU_API_KEY']; results=[]\n          def request(base,params):\n              last=None\n              for attempt in range(3):\n                  try:\n                      url=base+'?'+urllib.parse.urlencode(dict(params,key=key))\n                      req=urllib.request.Request(url,headers={'Accept':'application/json','User-Agent':'Starcore-Tianshu-B06-Acceptance'})\n                      with urllib.request.urlopen(req,timeout=20) as r: return r.status,r.read(4194304)\n                  except Exception as exc:\n                      last=exc\n                      if attempt<2: time.sleep(1.5*(attempt+1))\n              raise last\n          def rows(payload):\n              data=payload.get('data'); valid=0; schema_valid=0\n              if isinstance(data,list):\n                  for row in data:\n                      if isinstance(row,dict) and all(k in row for k in ('betNo','gmtBetNo','openNumber','block','hash','openTime')):\n                          schema_valid+=1\n                          nums=[int(x) for x in re.split(r'[,\\s-]+',str(row['openNumber']).strip()) if x]\n                          if len(nums)==10 and sorted(nums)==list(range(1,11)): valid+=1\n              return data,valid,schema_valid\n          for line,base in [('PRIMARY','https://api.duoqu.online/data'),('BACKUP','https://api1.duoqu.online/data')]:\n              status,raw=request(base,{'code':'Binance1-PK10','limit':20}); payload=json.loads(raw.decode('utf-8')); data,valid,schema_valid=rows(payload)\n              count=len(data) if isinstance(data,list) else 0\n              results.append({'line':line,'operation':'LATEST','http':status,'rows':count,'schema_valid':schema_valid,'valid_permutations':valid,'game':payload.get('lotteryCode',''),'ok':status==200 and payload.get('lotteryCode')=='Binance1-PK10' and count>0 and schema_valid==count and valid==count,'body_sha256':hashlib.sha256(raw).hexdigest()})\n              latest=data[0] if isinstance(data,list) and data else {}; raw_open=str(latest.get('openTime','')).strip(); m=re.search(r'(\\d{4})[-/](\\d{1,2})[-/](\\d{1,2})',raw_open)\n              if m: latest_date=datetime.date(int(m.group(1)),int(m.group(2)),int(m.group(3)))\n              else:\n                  try:\n                      ts=float(raw_open); ts=ts/1000.0 if ts>100000000000 else ts\n                      latest_date=datetime.datetime.fromtimestamp(ts,datetime.timezone(datetime.timedelta(hours=8))).date()\n                  except Exception:\n                      latest_date=datetime.datetime.now(datetime.timezone(datetime.timedelta(hours=8))).date()\n              date=(latest_date-datetime.timedelta(days=1)).strftime('%Y-%m-%d')\n              status,raw=request(base,{'code':'Binance1-PK10','date':date}); payload=json.loads(raw.decode('utf-8')); data,valid,schema_valid=rows(payload)\n              count=len(data) if isinstance(data,list) else 0\n              results.append({'line':line,'operation':'DATE','query_date':date,'http':status,'rows':count,'schema_valid':schema_valid,'valid_permutations':valid,'game':payload.get('lotteryCode',''),'ok':status==200 and payload.get('lotteryCode')=='Binance1-PK10' and count>0 and schema_valid==count and valid==count,'body_sha256':hashlib.sha256(raw).hexdigest()})\n          report={'game':'Binance1-PK10','requests':4,'latest_rate_limit_contract':'2 requests << 50/min','date_rate_limit_contract':'2 requests << 5/min','key_logged':False,'results':results,'all_ok':all(x['ok'] for x in results)}\n          open('reports/B06_LIVE_API_TEST.json','w',encoding='utf-8').write(json.dumps(report,ensure_ascii=False,indent=2)+'\\n')\n          print(json.dumps(report,ensure_ascii=False,indent=2))\n          if not report['all_ok']: raise SystemExit('B06_LIVE_API_FAILED')\n          PY\n"
s = s[:a] + replacement + s[b:]
old_push = '          git push origin HEAD:"$ACCEPTED_BRANCH"\n'
new_push = '          git push --force-with-lease origin HEAD:"$ACCEPTED_BRANCH"\n'
if s.count(old_push) != 1:
    raise SystemExit('ACCEPTED_PUSH_MATCH_COUNT=' + str(s.count(old_push)))
s = s.replace(old_push, new_push, 1)
required = ['betNo','gmtBetNo','openNumber','block','hash','openTime','https://api.duoqu.online/data','https://api1.duoqu.online/data','--force-with-lease']
missing = [x for x in required if x not in s]
if missing:
    raise SystemExit('MISSING_AFTER_PATCH=' + ','.join(missing))
p.write_text(s, encoding='utf-8')
print('B06_API_SCHEMA_PATCH=PASS')
